#!/usr/bin/env python3
"""Run the mandatory calibration, acknowledged commit, and power-cut matrix for GitHub CI."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
from dataclasses import dataclass
import json
from pathlib import Path
import shlex
import subprocess
import sys
from typing import Any

from ci_gate import POWER_CUT_SCENARIOS, validate_campaign_reports
from running_contract import RUNNING_TRIALS
from runner_common import require_executable, require_regular_file, write_json_exclusive


SCRIPT_DIR = Path(__file__).resolve().parent


@dataclass(frozen=True)
class CampaignStep:
    name: str
    command: list[str]
    report_path: Path


def build_campaign_plan(args: argparse.Namespace) -> list[CampaignStep]:
    repo_root = Path(args.repo_root).resolve()
    scratch_root = Path(args.scratch_root).resolve()
    common = [
        "--repo-root", str(repo_root),
        "--os-base-image", str(Path(args.os_base_image).resolve()),
        "--firmware-code", str(Path(args.firmware_code).resolve()),
        "--firmware-vars-template", str(Path(args.firmware_vars_template).resolve()),
        "--qemu", str(Path(args.qemu).resolve()),
        "--qemu-img", str(Path(args.qemu_img).resolve()),
        "--genisoimage", str(Path(args.genisoimage).resolve()),
        "--machine", args.machine,
        "--accel", args.accel,
        "--cpu", args.cpu,
        "--smp", "4",
        "--memory-mib", "4096",
    ]
    classpath = ["--host-classpath-file", str(Path(args.host_classpath_file).resolve()),
                 "--native-classifier", args.native_classifier]
    steps: list[CampaignStep] = []

    def add(name: str, runner: str, report_relative: str, extra: list[str], offset: int) -> None:
        command = [sys.executable, str(SCRIPT_DIR / runner), "--scratch-root", str(scratch_root / name),
                   *common, *extra, "--port-base", str(args.port_base + offset)]
        steps.append(CampaignStep(name, command, scratch_root / name / report_relative))

    add("calibration", "run_calibration.py", "results/ext4-crash-calibration-report.json",
        ["--phase1-timeout-seconds", "600", "--recovery-timeout-seconds", "600"], 0)
    add("namespace", "run_campaign.py", "results/actual-campaign-report.json",
        [*classpath, "--writer-timeout-seconds", "900", "--recovery-timeout-seconds", "900"], 10)
    for index, scenario in enumerate(POWER_CUT_SCENARIOS, start=2):
        add(scenario, "run_powercut_campaign.py", "results/actual-powercut-campaign-report.json",
            [*classpath, "--scenario", scenario, "--writer-timeout-seconds", "900",
             "--recovery-timeout-seconds", "900"], index * 10)
    for index, trial in enumerate(RUNNING_TRIALS, start=5):
        add(trial, "run_powercut_campaign.py", "results/actual-powercut-campaign-report.json",
            [*classpath, "--scenario", trial, "--writer-timeout-seconds", "900",
             "--recovery-timeout-seconds", "900"], index * 10)
    if not 1 <= args.port_base <= 65534 - (len(steps) - 1) * 10:
        raise ValueError("--port-base is outside the range needed for all sequential campaign ports")
    return steps


def prepare_output_root(path: Path) -> Path:
    if path.exists() or path.is_symlink():
        if path.is_symlink() or not path.is_dir() or any(path.iterdir()):
            raise FileExistsError(f"refusing nonempty or unsafe CI output root: {path}")
    else:
        path.mkdir(parents=True)
    return path.resolve(strict=True)


def _read_report(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"campaign report is not a JSON object: {path}")
    return value


def run_plan(steps: list[CampaignStep], repo_root: Path, output_root: Path) -> dict[str, Any]:
    completed: list[str] = []
    logs = output_root / "runner-logs"
    logs.mkdir()
    first_command = steps[0].command
    statement_command = next(step.command for step in steps if step.name == "namespace")

    def argument_value(flag: str, command: list[str] = first_command) -> str:
        try:
            return command[command.index(flag) + 1]
        except (ValueError, IndexError) as error:
            raise ValueError(f"campaign plan is missing {flag}") from error

    write_json_exclusive(output_root / "ci-campaign-command-plan.json", {
        "guest_machine": argument_value("--machine"),
        "guest_accelerator": argument_value("--accel"),
        "guest_cpu": argument_value("--cpu"),
        "native_classifier": argument_value("--native-classifier", statement_command),
        "required_order": [step.name for step in steps],
        "commands": [{"name": step.name, "command": step.command, "report": str(step.report_path)}
                     for step in steps],
    })
    reports: dict[str, Any] = {}
    try:
        for step in steps:
            log_path = logs / f"{step.name}.log"
            print(f"Running {step.name}: {shlex.join(step.command)}", flush=True)
            with log_path.open("x", encoding="utf-8") as log:
                process = subprocess.run(step.command, cwd=repo_root, stdout=log,
                                         stderr=subprocess.STDOUT, check=False)
            if process.returncode != 0:
                raise RuntimeError(f"{step.name} exited {process.returncode}; see {log_path}")
            if not step.report_path.is_file():
                raise FileNotFoundError(f"{step.name} did not produce its required report: {step.report_path}")
            reports[step.name] = _read_report(step.report_path)
            completed.append(step.name)
        summary = validate_campaign_reports(
            reports["calibration"], reports["namespace"],
            [reports[scenario] for scenario in POWER_CUT_SCENARIOS],
            [reports[trial] for trial in RUNNING_TRIALS],
        )
        summary["runner_order"] = completed
        write_json_exclusive(output_root / "ci-campaign-summary.json", summary)
        print(json.dumps(summary, indent=2, sort_keys=True), flush=True)
        return summary
    except BaseException as error:
        failure = {
            "status": "FAILED",
            "completed_campaigns": completed,
            "current_campaign": steps[len(completed)].name if len(completed) < len(steps) else None,
            "error_type": type(error).__name__,
            "error": str(error),
        }
        write_json_exclusive(output_root / "ci-campaign-failure.json", failure)
        raise


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", required=True, type=Path)
    parser.add_argument("--scratch-root", required=True, type=Path)
    parser.add_argument("--os-base-image", required=True, type=Path)
    parser.add_argument("--firmware-code", required=True, type=Path)
    parser.add_argument("--firmware-vars-template", required=True, type=Path)
    parser.add_argument("--qemu", required=True, type=Path)
    parser.add_argument("--qemu-img", required=True, type=Path)
    parser.add_argument("--genisoimage", required=True, type=Path)
    parser.add_argument("--host-classpath-file", required=True, type=Path)
    parser.add_argument("--machine", choices=("q35",), default="q35")
    parser.add_argument("--accel", choices=("kvm",), default="kvm")
    parser.add_argument("--cpu", choices=("host",), default="host")
    parser.add_argument("--native-classifier", choices=("linux",), default="linux")
    parser.add_argument("--port-base", type=int, default=23000)
    args = parser.parse_args()
    try:
        repo_root = Path(args.repo_root).expanduser().resolve(strict=True)
        if not repo_root.is_dir() or not (repo_root / ".m2_repo").is_dir():
            raise FileNotFoundError("repository and workspace .m2_repo are required")
        args.repo_root = repo_root
        args.os_base_image = require_regular_file(args.os_base_image, "provisioned guest image")
        args.firmware_code = require_regular_file(args.firmware_code, "x86_64 UEFI firmware code")
        args.firmware_vars_template = require_regular_file(args.firmware_vars_template, "x86_64 UEFI vars template")
        args.qemu = require_executable(args.qemu, "qemu-system-x86_64")
        args.qemu_img = require_executable(args.qemu_img, "qemu-img")
        args.genisoimage = require_executable(args.genisoimage, "genisoimage")
        args.host_classpath_file = require_regular_file(args.host_classpath_file, "exact-build guest classpath")
        output_root = prepare_output_root(args.scratch_root.expanduser().absolute())
        args.scratch_root = output_root
        steps = build_campaign_plan(args)
        run_plan(steps, repo_root, output_root)
        return 0
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError) as error:
        print(f"LMDB QEMU campaign driver failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
